create table "devcontrol"."devworkruns" (
  "id"          bigint                   generated by default as identity not null,
  "request_id"  bigint                   not null,
  "run_status"  text                     not null default 'queued'::text,
  "started_at"  timestamp with time zone,
  "finished_at" timestamp with time zone,
  "result"      jsonb,
  "created_at"  timestamp with time zone not null default now(),
  constraint "devworkruns_pkey" primary key (id),
  constraint "devworkruns_request_id_fkey" foreign key (request_id) references devcontrol.devworkrequests(id) on delete cascade
);

grant delete, insert, maintain, references, select, trigger, truncate, update on table "devcontrol"."devworkruns" to "postgres";
